import json, urllib.request, os, sys
sys.path.insert(0, os.path.dirname(__file__))
from data import T, PREV, NEXT
pts = {}
for line in open(os.path.join(os.path.dirname(__file__), '..', 'pts.txt'), encoding='utf-8'):
    if '|' in line:
        n, c = line.strip().split('|'); pts[n] = c
pts['Ostermiething Firma'] = '12.8417,48.0428'
rows = [PREV] + [r for r in T if r[0] != 'W2'] + [NEXT]
pairs = set()
for a, b in zip(rows, rows[1:]):
    if a[3] != b[3]: pairs.add((a[3], b[3]))
# also Hall<->Firma both ways and Ort->Firma for Szenario
cache_f = os.path.join(os.path.dirname(__file__), 'routes.json')
cache = json.load(open(cache_f)) if os.path.exists(cache_f) else {}
for a, b in sorted(pairs):
    k = a + '>' + b
    if k in cache: continue
    url = f"https://router.project-osrm.org/route/v1/driving/{pts[a]};{pts[b]}?overview=false"
    d = json.load(urllib.request.urlopen(url, timeout=30))
    cache[k] = [round(d['routes'][0]['distance'] / 1000, 1), round(d['routes'][0]['duration'] / 60)]
    print(k, cache[k])
json.dump(cache, open(cache_f, 'w'), indent=0, ensure_ascii=False)

